function createFakeUnixStandaloneInstall(installRoot, home) {
  const dir = path.join(installRoot, 'lib', 'qwen-code');
  for (const name of ['bin', 'node/bin']) mkdirSync(path.join(dir, name), { recursive: true });
  mkdirSync(path.join(installRoot, 'bin'), { recursive: true });
  mkdirSync(path.join(home, '.qwen'), { recursive: true });
  writeFileSync(path.join(dir, 'manifest.json'), JSON.stringify({ name: '@qwen-code/qwen-code', target: 'linux-x64' }));
  for (const name of ['bin/qwen', 'node/bin/node']) writeFileSync(path.join(dir, name), '#!/bin/sh\nexit 0\n', { mode: 0o755 });
  writeFileSync(path.join(installRoot, 'bin', 'qwen'), `#!/bin/sh\nexec "${dir}/bin/qwen" "$@"\n`, { mode: 0o755 });
  writeFileSync(path.join(home, '.qwen', 'source.json'), '{"source":"smoke"}\n');
}

